1	import 'dotenv/config';
2	
3	import { ClientSecretCredential } from '@azure/identity';
4	import { BlobServiceClient, ContainerClient } from '@azure/storage-blob';
5	import { PrismaMariaDb } from '@prisma/adapter-mariadb';
6	import { Prisma, PrismaClient } from 'prisma/generated/client';
7	import { AUTH_TABLES, GAME_DATA_TABLES } from './table-manifest';
8	
9	const adapter = new PrismaMariaDb(process.env.DATABASE_URL!);
10	const prisma = new PrismaClient({ adapter });
11	
12	async function streamToBuffer(
13	    readableStream: NodeJS.ReadableStream,
14	): Promise<Buffer> {
15	    return new Promise((resolve, reject) => {
16	        const chunks: Uint8Array[] = [];
17	        readableStream.on('data', (data) => {
18	            chunks.push(data instanceof Buffer ? data : Buffer.from(data));
19	        });
20	        readableStream.on('end', () => {
21	            resolve(Buffer.concat(chunks));
22	        });
23	        readableStream.on('error', reject);
24	    });
25	}
26	
27	async function downloadAndParseJson(
28	    containerClient: ContainerClient,
29	    blobName: string,
30	): Promise<unknown> {
31	    try {
32	        const blobClient = containerClient.getBlobClient(blobName);
33	        const downloadBlockBlobResponse = await blobClient.download(0);
34	
35	        if (!downloadBlockBlobResponse.readableStreamBody) {
36	            throw new Error(`Reading  ${blobName} failed`);
37	        }
38	
39	        const downloadedContent = (
40	            await streamToBuffer(downloadBlockBlobResponse.readableStreamBody)
41	        ).toString();
42	
43	        return JSON.parse(downloadedContent);
44	    } catch (error) {
45	        console.error(
46	            `An error occurred during ${blobName} download: ${error}`,
47	        );
48	        throw error;
49	    }
50	}
51	
52	// Chunks per INSERT to stay within MariaDB's max_allowed_packet limit.
53	const CHUNK_SIZE = 500;
54	
55	async function seedTable(
56	    containerClient: ContainerClient,
57	    fileName: string,
58	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
59	    model: {
60	        createMany: (args: {
61	            data: any[];
62	        }) => Prisma.PrismaPromise<Prisma.BatchPayload>;
63	    },
64	): Promise<void> {
65	    console.log(`Starting: ${fileName}`);
66	    const parsed = await downloadAndParseJson(containerClient, fileName);
67	    if (!Array.isArray(parsed)) {
68	        throw new Error(
69	            `Expected ${fileName} to contain a JSON array, got ${typeof parsed}`,
70	        );
71	    }
72	    const dataItems: unknown[] = parsed;
73	    const chunks: Prisma.PrismaPromise<Prisma.BatchPayload>[] = [];
74	    for (let i = 0; i < dataItems.length; i += CHUNK_SIZE) {
75	        chunks.push(
76	            model.createMany({ data: dataItems.slice(i, i + CHUNK_SIZE) }),
77	        );
78	    }
79	    await prisma.$transaction(chunks, { timeout: 120_000 });
80	    console.log(`Complete:  ${fileName}`);
81	}
82	
83	async function main() {
84	    console.log('🌱 Seed script started');
85	
86	    // Read secrets directly from environment - works in any environment
87	    const tenantId = process.env.AZURE_TENANT_ID;
88	    if (!tenantId) throw new Error('AZURE_TENANT_ID undefined');
89	
90	    const clientId = process.env.STORAGE_CLIENT_ID;
91	    if (!clientId) throw new Error('STORAGE_CLIENT_ID undefined');
92	
93	    const clientSecret = process.env.STORAGE_CLIENT_SECRET;
94	    if (!clientSecret) throw new Error('STORAGE_CLIENT_SECRET undefined');
95	
96	    const storageAccountName = 'nextwwwtoastboy';
97	    const containerName = 'dbseeddata';
98	
99	    const credentials = new ClientSecretCredential(
100	        tenantId,
101	        clientId,
102	        clientSecret,
103	    );
104	    const blobServiceClient = new BlobServiceClient(
105	        `https://${storageAccountName}.blob.core.windows.net`,
106	        credentials,
107	    );
108	
109	    const containerClient = blobServiceClient.getContainerClient(containerName);
110	
111	    // Delete non-seeded tables that reference seeded rows before wiping the seeded tables.
112	    // contactEnquiry must precede emailVerification (FK reference).
113	    await prisma.contactEnquiry.deleteMany();
114	    await prisma.emailVerification.deleteMany();
115	    await prisma.gameInvitation.deleteMany();
116	    for (const { getModel } of [...GAME_DATA_TABLES].reverse()) {
117	        await getModel(prisma).deleteMany();
118	    }
119	
120	    for (const { fileName, getModel } of GAME_DATA_TABLES) {
121	        await seedTable(containerClient, fileName, getModel(prisma));
122	    }
123	
124	    // session references user; deleteMany does not trigger the onDelete:Cascade
125	    // emulated by relationMode=prisma, so it must be cleared explicitly.
126	    await prisma.session.deleteMany();
127	    for (const { getModel } of [...AUTH_TABLES].reverse()) {
128	        await getModel(prisma).deleteMany();
129	    }
130	    for (const { fileName, getModel } of AUTH_TABLES) {
131	        await seedTable(containerClient, fileName, getModel(prisma));
132	    }
133	
134	    console.log('🌱 Database seeding complete.');
135	}
136	
137	main()
138	    .catch((e) => {
139	        console.error(e);
140	        process.exit(1);
141	    })
142	    .finally(async () => {
143	        await prisma.$disconnect();
144	        process.exit(0);
145	    });
