12	/**
13	 * Health check endpoint for Docker healthcheck and monitoring.
14	 * Verifies both application and database connectivity.
15	 * Uses connection pooling efficiently to avoid connection warnings.
16	 */
17	export async function GET() {
18	    try {
19	        // Test database connectivity with a simple query
20	        // Prisma reuses connections from the pool, so no explicit disconnect needed
21	        await prisma.$queryRaw`SELECT 1`;
22	
23	        return NextResponse.json(
24	            {
25	                status: 'healthy',
26	                database: 'connected',
27	                timestamp: new Date().toISOString(),
28	            },
29	            {
30	                status: 200,
31	                headers: {
32	                    Connection: 'close',
33	                    'Cache-Control': 'no-store, no-cache, must-revalidate',
34	                },
35	            },
36	        );
37	    } catch (error) {
38	        const normalizedError = normalizeUnknownError(error, {
39	            publicMessage: 'Health check failed',
40	            details: {
41	                route: '/api/health',
42	            },
43	        });
44	        captureUnexpectedError(normalizedError, {
45	            layer: 'route',
46	            action: 'healthCheck',
47	            route: '/api/health',
48	        });
49	
50	        /**
51	         * Normalise generic upstream/internal failures (surfaced as HTTP 500 by
52	         * `toHttpErrorResponse`, such as Prisma/database connectivity issues or
53	         * transient infrastructure errors) to HTTP 503 so that orchestrators and
54	         * external monitors treat the service as temporarily unavailable rather
55	         * than permanently broken.
56	         *
57	         * Non-500 statuses are passed through unchanged so that deliberate
58	         * application-level responses (e.g. validation 4xx or explicit 503s)
59	         * remain visible to callers and are not masked by this health-specific
60	         * normalisation.
61	         */
62	
63	        const { status, message } = toHttpErrorResponse(
64	            normalizedError,
65	            'Health check failed',
66	        );
67	
68	        return NextResponse.json(
69	            {
70	                status: 'unhealthy',
71	                database: 'disconnected',
72	                error: message,
73	                timestamp: new Date().toISOString(),
74	            },
75	            {
76	                status: status === 500 ? 503 : status,
77	                headers: {
78	                    Connection: 'close',
79	                    'Cache-Control': 'no-store, no-cache, must-revalidate',
80	                },
81	            },
82	        );
83	    }
84	}
