75	
76	    const result = { ...secrets };
77	    const secretsDir = process.env.SECRETS_DIR;
78	
79	    if (secretsDir) {
80	        for (const key of Object.keys(secrets) as (keyof typeof secrets)[]) {
81	            const value = readFileIfExists(path.join(secretsDir, key));
82	
83	            if (value !== undefined) {
84	                result[key] = value;
85	            }
86	        }
87	    }
88	
89	    const isProduction = process.env.NODE_ENV === 'production';
90	    const missingSecrets = Object.entries(result)
91	        .filter(([key, value]) => {
92	            const isMissing =
93	                value === undefined || value === null || value === '';
94	            if (!isMissing) return false;
95	
96	            // Production-only secrets (e.g. Graph API email) are allowed to be
97	            // absent outside production; all other secrets are always required.
98	            if (
